products.forEach((p,i)=>Object.assign(p,{cost:[2800,2300,1100,1600,1900,4200][i],minStock:i===4?20:10,active:true,service:false,openingDone:true}));
const parties=[...customers.map(c=>Object.assign(c,{customer:true,supplier:false,address:'الرياض',active:true})),{id:201,name:'شركة مذاق للتوريد',phone:'055 800 2001',address:'الرياض · حي السلي',customer:false,supplier:true,active:true},{id:202,name:'مؤسسة رُكن الضيافة',phone:'050 800 2002',address:'الرياض · حي العليا',customer:false,supplier:true,active:true}];
const purchases=[{id:5002,kind:'purchase',partyId:201,party:'شركة مذاق للتوريد',date:'اليوم، ٨:٣٠ ص',total:56000,due:26000,items:[{id:1,qty:20,price:2800,unit:products[0].unit}]},{id:5001,kind:'purchase',partyId:202,party:'مؤسسة رُكن الضيافة',date:'أمس، ٣:١٠ م',total:22000,due:0,items:[{id:3,qty:20,price:1100,unit:products[2].unit}]}];
const receipts=[{id:7001,kind:'receiving',partyId:201,party:'شركة مذاق للتوريد',date:'اليوم، ٧:٤٥ ص',total:23000,due:0,status:'waiting',items:[{id:2,qty:10,price:2300,unit:products[1].unit}]}];
const accounts=[{id:'cash',name:'الصندوق الرئيسي',balance:1245000,type:'cash'},{id:'bank',name:'حساب الراجحي',balance:2860000,type:'bank'}];
const movements=[{id:1,productId:1,title:'فاتورة بيع INV-1048',qty:-5,cost:2800,note:'بيع إلى أحمد العتيبي',date:'اليوم، ١٠:٤٢ ص'},{id:2,productId:1,title:'فاتورة شراء PUR-5002',qty:20,cost:2800,note:'شركة مذاق للتوريد',date:'اليوم، ٨:٣٠ ص'},{id:3,productId:2,title:'استلام سريع REC-7001',qty:10,cost:2300,note:'تكلفة تقديرية · بانتظار الفاتورة',date:'اليوم، ٧:٤٥ ص'}];
const operations=[{id:101,kind:'receipt',label:'قبض من عميل',partyId:2,party:'مؤسسة نواة',amount:12000,account:'cash',date:'اليوم، ٩:٥٥ ص',note:'دفعة من حساب العميل',seed:true},{id:100,kind:'expense',label:'مصروف',amount:4500,account:'cash',date:'أمس، ٦:١٥ م',note:'مستلزمات المحل',seed:true}];
const users=[{id:1,name:'عبدالله محمد',username:'abdullah',role:'owner',active:true},{id:2,name:'محمد سالم',username:'mohammed',role:'seller',active:true},{id:3,name:'خالد علي',username:'khaled',role:'accountant',active:true}];
const categories=[...new Set(products.map(p=>p.category))];
const units=[...new Set(products.map(p=>p.unit))];
const demo={drafts:{sale:null,purchase:null,receiving:null},productId:null,partyId:null,partyRole:'customer',productFilter:'all',partyFilter:'customer',inventoryFilter:'all',form:{},financeKind:'receipt',reportTab:'trial',query:'',operationId:null,returnDoc:null,stockOrigin:'stock',backupAuto:true,pos:false,backups:[],audit:[],reportPeriod:'month'};
const opLabels={receipt:'قبض من عميل',payment:'سداد مورد',expense:'مصروف',transfer:'تحويل بين الحسابات',capital:'إضافة رأس مال',drawing:'مسحوبات شخصية'};
const roleLabels={owner:'المالك',seller:'بائع',accountant:'محاسب'};
const getProduct=()=>products.find(p=>p.id===demo.productId);
const getParty=()=>parties.find(p=>p.id===demo.partyId);
const isBuying=()=>state.kind==='purchase'||state.kind==='receiving';
const invoiceSet=()=>state.kind==='sale'?documents:state.kind==='purchase'?purchases:receipts;
const invoiceList=()=>state.kind==='sale'?'sales':state.kind==='purchase'?'purchases':'receiving';
const partyLabel=()=>isBuying()?'المورد':'العميل';
const invoiceLabel=()=>state.kind==='receiving'?'استلام سريع':state.kind==='purchase'?'فاتورة شراء':'فاتورة بيع';
const docPrefix=d=>d.kind==='purchase'?'PUR':d.kind==='receiving'?'REC':'INV';
const docNet=d=>d.total-(d.returned||0);
const baseQty=(line)=>line.qty*(line.factor||1);
const baseCost=p=>p.cost||0;
function logDemo(title){demo.audit.unshift({title,time:'الآن',name:demoShop.fullName||'عبدالله'})}
function demoHint(text='البيانات والعمليات توضيحية، وتبقى داخل هذه التجربة فقط.'){return `<div class="helper">${icon('info')}<span>${text}</span></div>`}
function emptyView(title,message='جرّب تغيير البحث أو التصفية.'){return `<div class="empty">${icon('search')}<h3>${title}</h3><p>${message}</p></div>`}
function sectionTitle(t,action=''){return `<div class="section-heading"><h3>${t}</h3>${action}</div>`}
function actionButton(t,a,i='plus',data=''){return `<button class="primary full" data-action="${a}" ${data}>${icon(i)}${t}</button>`}
function formField(label,name,value='',options={}){const{type='text',required=false,min='',step='',placeholder='',max='',readonly=false}=options;return `<label class="field">${label}<input name="${name}" data-field="${name}" type="${type}" value="${esc(value??'')}" ${required?'required':''} ${min!==''?`min="${min}"`:''} ${max!==''?`max="${max}"`:''} ${step?`step="${step}"`:''} ${type==='number'?'inputmode="decimal"':''} ${readonly?'readonly':''} placeholder="${placeholder}" ${name==='phone'?'dir="ltr"':''}></label>`}
function selectField(label,name,value,choices){return `<label class="field">${label}<select name="${name}" aria-label="${esc(label)}" data-field="${name}">${choices.map(c=>{const[v,t]=Array.isArray(c)?c:[c,c];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`}
function checkField(label,name,checked,sub=''){return `<label class="switch-row"><span>${label}${sub?`<small>${sub}</small>`:''}</span><input type="checkbox" name="${name}" data-field="${name}" ${checked?'checked':''}><span class="switch-track" aria-hidden="true"></span></label>`}
function formPage(title,body,id,label,subtitle=''){return header(title,{back:true,sub:subtitle,action:'<span class="badge-outline">معاينة</span>'})+`<main class="app-scroll"><form id="${id}">${body}<div id="form-error" role="alert"></div></form></main><footer class="action-bar"><button class="primary full" type="submit" form="${id}">${icon('check')}${label}</button></footer>`}
function formError(message){const e=document.querySelector('#form-error')||document.querySelector('#payment-error');if(e){e.innerHTML=`<div class="inline-error">${message}</div>`;e.scrollIntoView({block:'nearest'})}else toast(message)}
function infoRow(label,value){return `<div class="summary-line"><span class="muted">${label}</span><span>${value}</span></div>`}
function goDemo(view){if(['parties','purchases','receiving','stock','reports','settings','profile','users','backups','store-settings'].includes(view))state.tab='more';if(['products','product-detail','product-form','inventory-detail','opening'].includes(view))state.tab='products';navigate(view)}
function dataChips(options,current,action){return `<div class="chips" role="group">${options.map(([v,t])=>`<button class="chip ${v===current?'active':''}" data-action="${action}" data-value="${v}" aria-pressed="${v===current}">${t}</button>`).join('')}</div>`}
function searchBox(id,value,placeholder){return `<div class="search">${icon('search')}<input id="${id}" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(value)}"></div>`}
function newProduct(id=null){demo.productId=id;const p=getProduct();demo.form=p?{...p,price:p.price/100,cost:p.cost/100,factor:p.factor||1}:{name:'',code:'',category:categories[0],unit:units[0],price:'',cost:'',minStock:'',service:false,active:true,alternateUnit:'',factor:1};goDemo('product-form')}
function catalogRows(){const list=products.filter(p=>(demo.productFilter==='all'||demo.productFilter==='low'&&!p.service&&p.stock<=p.minStock||demo.productFilter==='services'&&p.service)&&(p.name.includes(state.productQuery)||p.code.includes(state.productQuery)));return list.map(p=>`<button class="record-row" data-action="product-detail" data-id="${p.id}"><span class="item-visual">${icon('package')}</span><div class="record-body"><div class="row between"><b>${esc(p.name)}</b>${icon('chevron-left')}</div><small>${esc(p.category||'بدون تصنيف')}</small><div class="row between record-foot"><span>${amount(p.price)}</span><span class="${!p.service&&p.stock<=p.minStock?'stock-low':'muted'}">${p.service?'خدمة':`${p.stock} ${esc(p.unit)}`}</span></div></div></button>`).join('')||emptyView('لا توجد منتجات مطابقة')}
function catalogPage(){return header('المنتجات',{sub:`${products.length} منتجات وخدمات`,action:`<button class="icon-btn" data-action="references" aria-label="التصنيفات والوحدات">${icon('sliders-horizontal')}</button>`})+`<main class="app-scroll">${actionButton('منتج جديد','product-new')}${searchBox('catalog-search',state.productQuery,'ابحث باسم المنتج أو الباركود')}${dataChips([['all','الكل'],['low','منخفض المخزون'],['services','الخدمات']],demo.productFilter,'catalog-filter')}<div id="catalog-results">${catalogRows()}</div>${demoHint('رمز المنتج موحّد لجميع المنتجات؛ لا تحتاج إلى صور أو أيقونات خاصة بكل منتج.')}</main>`+nav()}
function productDetailPage(){const p=getProduct();return header('تفاصيل المنتج',{back:true,action:`<button class="text-button" data-action="product-edit">تعديل</button>`})+`<main class="app-scroll"><div class="entity-heading"><span class="entity-icon">${icon('package')}</span><h2>${esc(p.name)}</h2><p>${esc(p.category||'بدون تصنيف')} · ${esc(p.unit)}</p><span class="status ${p.active?'':'draft'}">${p.active?'نشط':'موقوف'}${p.service?' · خدمة':''}</span></div>${!p.service?`<section class="stock-hero"><span class="small muted">الكمية المتاحة</span><div><strong>${p.stock}</strong><span>${esc(p.unit)}</span></div><span class="status ${p.stock<=p.minStock?'due':''}">${p.stock<=p.minStock?'وصل إلى حد التنبيه':'المخزون متوفر'}</span></section>`:''}<section class="panel">${sectionTitle('الأسعار')}${infoRow('سعر البيع',amount(p.price))}${infoRow('تكلفة الوحدة',amount(p.cost))}${infoRow('الباركود',`<span class="tiny" dir="ltr">${esc(p.code||'—')}</span>`)}${p.alternateUnit?infoRow('الوحدة الإضافية',`${esc(p.alternateUnit)} = ${p.factor} ${esc(p.unit)}`):''}</section>${!p.service?`<button class="customer-select" data-action="product-inventory"><span class="customer-icon">${icon('boxes')}</span><span>حركة المخزون والجرد<small>الاستلام والبيع والتسويات</small></span>${icon('chevron-left')}</button>${!p.openingDone?`<button class="dashed" data-action="opening">${icon('plus')} إضافة مخزون افتتاحي</button>`:''}`:''}</main>`}
function productFormPage(){const p=demo.form;return formPage(demo.productId?'تعديل المنتج':'منتج جديد',`<section class="panel">${sectionTitle('بيانات المنتج')}${selectField('النوع','service',String(p.service),[['false','منتج مخزني'],['true','خدمة']])}${formField('اسم المنتج','name',p.name,{required:true})}${selectField('التصنيف','category',p.category,['',...categories])}${formField('الباركود (اختياري)','code',p.code)}${selectField('الوحدة الأساسية','unit',p.unit,units)}</section><section class="panel">${sectionTitle('الأسعار')}${formField('سعر البيع (ر.س)','price',p.price,{type:'number',min:0,step:'.01',required:true})}${formField('تكلفة الوحدة (ر.س)','cost',p.cost,{type:'number',min:0,step:'.01',required:!p.service})}</section>${!p.service?`<section class="panel">${sectionTitle('المخزون والوحدات')}${formField('حد تنبيه المخزون','minStock',p.minStock,{type:'number',min:0,step:'.001'})}${selectField('وحدة إضافية (اختياري)','alternateUnit',p.alternateUnit,[['','بدون وحدة إضافية'],...units.filter(u=>u!==p.unit)])}${p.alternateUnit?formField(`عدد ${p.unit} في ${p.alternateUnit}`,'factor',p.factor,{type:'number',min:'.001',step:'.001',required:true}):''}</section>`:''}<section class="panel">${checkField('المنتج نشط','active',p.active,'يظهر عند إضافة بنود الفاتورة')}</section>${demoHint()}`,'product-form','حفظ المنتج')}
function openingPage(){const p=getProduct();return formPage('مخزون افتتاحي',`<div class="welcome-note"><b>${esc(p.name)}</b>سجّل الكمية الموجودة قبل أول حركة على المنتج. تُستخدم تكلفة الوحدة المحفوظة.</div><section class="panel">${formField(`الكمية (${p.unit})`,'quantity',demo.form.quantity,{type:'number',min:'.001',step:'.001',required:true})}${infoRow('تكلفة الوحدة',amount(p.cost))}<div class="summary-line total"><span>القيمة الافتتاحية</span><span id="opening-value">${amount(Math.round(Number(demo.form.quantity||0)*p.cost))}</span></div></section>`,'opening-form','حفظ المخزون الافتتاحي')}
function stockRows(){return products.filter(p=>!p.service&&(demo.inventoryFilter!=='low'||p.stock<=p.minStock)&&p.name.includes(demo.query)).map(p=>`<button class="record-row" data-action="inventory-detail" data-id="${p.id}"><span class="item-visual">${icon('package')}</span><div class="record-body"><b>${esc(p.name)}</b><div class="row between record-foot"><small>${esc(p.unit)}</small><span class="${p.stock<=p.minStock?'stock-low':''}">${p.stock} متاح</span></div></div>${icon('chevron-left')}</button>`).join('')||emptyView('لا توجد منتجات مطابقة')}
function stockPage(){return header('المخزون والاستلام',{back:true})+`<main class="app-scroll"><div class="metrics-pair"><div><span>قيمة المخزون</span><strong>${amount(products.filter(p=>!p.service).reduce((n,p)=>n+Math.round(p.stock*p.cost),0))}</strong></div><div><span>منخفض المخزون</span><strong>${products.filter(p=>!p.service&&p.stock<=p.minStock).length}<small> منتجات</small></strong></div></div><button class="customer-select" data-action="receiving-list"><span class="customer-icon">${icon('truck')}</span><span>الاستلام السريع<small>${receipts.filter(d=>d.status==='waiting').length} استلامات تنتظر فاتورة المورد</small></span>${icon('chevron-left')}</button>${searchBox('stock-search',demo.query,'ابحث في المخزون')}${dataChips([['all','كل المنتجات'],['low','منخفض المخزون']],demo.inventoryFilter,'stock-filter')}<div id="stock-results">${stockRows()}</div></main>`+nav()}
function movementRows(p){const list=movements.filter(m=>m.productId===p.id);return list.length?list.map(m=>`<div class="timeline-row"><span class="timeline-dot ${m.qty<0?'out':''}"></span><div><b>${esc(m.title)}</b><small>${esc(m.note)} · ${esc(m.date)}</small></div><strong class="num ${m.qty<0?'muted':'positive'}" dir="ltr">${m.qty>0?'+':''}${m.qty}</strong></div>`).join(''):'<p class="small muted">لا توجد حركات مسجلة في هذه التجربة.</p>'}
function inventoryDetailPage(){const p=getProduct();return header('حركة المخزون',{back:true,sub:p.name})+`<main class="app-scroll"><section class="stock-hero"><span class="small muted">المتاح من ${esc(p.name)}</span><div><strong>${p.stock}</strong><span>${esc(p.unit)}</span></div><div class="summary-line"><span>متوسط التكلفة</span>${amount(p.cost)}</div></section><div class="metrics-pair"><div><span>قيمة المخزون</span><strong>${amount(Math.round(p.stock*p.cost))}</strong></div><div><span>حد التنبيه</span><strong>${p.minStock}<small> ${esc(p.unit)}</small></strong></div></div><button class="secondary full" data-action="adjust-stock">${icon('clipboard-check')} جرد وتسوية المخزون</button><div style="margin-top:24px">${sectionTitle('حركة المنتج')}${movementRows(p)}</div>${demoHint()}</main>`}
function partyBalance(p,role=demo.partyRole){const source=role==='supplier'?purchases:documents;let due=source.filter(d=>d.partyId===p.id||d.party===p.name).reduce((n,d)=>n+d.due,0);return due-(p[role==='supplier'?'supplierAdvance':'customerAdvance']||0)}
function partyRows(){return parties.filter(p=>p[demo.partyFilter]&&(p.name.includes(demo.query)||p.phone.includes(demo.query))).map(p=>`<button class="record-row" data-action="party-detail" data-id="${p.id}"><span class="avatar">${esc(p.name[0])}</span><div class="record-body"><b>${esc(p.name)}</b><div class="row between record-foot"><small dir="ltr">${esc(p.phone||'—')}</small><span class="${partyBalance(p,demo.partyFilter)>0?'stock-low':'muted'}">${amount(partyBalance(p,demo.partyFilter))}</span></div></div>${icon('chevron-left')}</button>`).join('')||emptyView('لا توجد أطراف مطابقة')}
function partiesListPage(){return header('العملاء والموردون',{back:true})+`<main class="app-scroll">${actionButton('عميل أو مورد جديد','party-new','user-round-plus')}${searchBox('party-search',demo.query,'ابحث بالاسم أو الهاتف')}${dataChips([['customer','العملاء'],['supplier','الموردون']],demo.partyFilter,'party-filter')}<div id="party-results">${partyRows()}</div><p class="list-note">الرصيد الموجب مستحق، والسالب دفعة مقدمة.</p></main>`+nav()}
function partyDetailPage(){const p=getParty(),supplier=demo.partyRole==='supplier',source=supplier?purchases:documents,docs=source.filter(d=>d.partyId===p.id||d.party===p.name);return header('كشف وبيانات الطرف',{back:true,action:`<button class="text-button" data-action="party-edit">تعديل</button>`})+`<main class="app-scroll"><div class="entity-heading"><span class="entity-icon">${icon('user-round')}</span><h2>${esc(p.name)}</h2><p dir="ltr">${esc(p.phone||'—')}</p><span class="status">${p.customer?'عميل':''}${p.customer&&p.supplier?' · ':''}${p.supplier?'مورد':''}</span></div>${p.customer&&p.supplier?dataChips([['customer','حساب العميل'],['supplier','حساب المورد']],demo.partyRole,'party-statement-role'):''}<section class="stock-hero"><span class="small muted">${supplier?'المستحق للمورد':'المستحق على العميل'}</span><div><strong>${amount(partyBalance(p))}</strong></div><span class="tiny muted">الرصيد السالب دفعة مقدمة لصالح الطرف</span></section><div class="quick-actions"><button class="quick-action" data-action="party-voucher">${icon('wallet')}${supplier?'سداد مورد':'قبض دفعة'}</button><button class="quick-action" data-action="party-invoice">${icon('receipt-text')}${supplier?'فاتورة شراء':'فاتورة بيع'}</button></div>${sectionTitle('كشف الحساب')}${docs.map(d=>`<button class="ledger-row" data-action="any-document" data-id="${d.id}" data-kind="${supplier?'purchase':'sale'}"><div><b>${supplier?'فاتورة شراء':'فاتورة بيع'} <span dir="ltr">${docPrefix(d)}-${d.id}</span></b><small>${esc(d.date)}</small></div><div class="ledger-amount">${amount(docNet(d))}<small>متبقي ${money(d.due)} ر.س</small></div></button>`).join('')}${operations.filter(o=>o.partyId===p.id&&(supplier?o.kind==='payment':o.kind==='receipt')).map(operationRow).join('')}${!docs.length?'<p class="small muted">لا توجد فواتير لهذا الطرف في التجربة.</p>':''}${demoHint()}</main>`}
function newParty(id=null){demo.partyId=id;demo.form=id?{...getParty()}:{name:'',phone:'',address:'',customer:demo.partyFilter==='customer',supplier:demo.partyFilter==='supplier',active:true};goDemo('party-form')}
function partyFormPage(){const p=demo.form;return formPage(demo.partyId?'تعديل الطرف':'طرف جديد',`<section class="panel">${sectionTitle('بيانات الطرف')}${formField('الاسم','name',p.name,{required:true})}${formField('الهاتف (اختياري)','phone',p.phone,{type:'tel'})}${formField('العنوان (اختياري)','address',p.address)}</section><section class="panel">${sectionTitle('يتعامل مع المحل بصفته')}${checkField('عميل','customer',p.customer)}${checkField('مورد','supplier',p.supplier)}${checkField('الطرف نشط','active',p.active)}</section>${demoHint('يمكن للطرف نفسه أن يكون عميلًا وموردًا، ولكل دور كشف حساب مستقل.')}`,'party-form','حفظ البيانات')}
function buyingRows(kind){const list=kind==='receiving'?receipts:purchases;return list.filter(d=>d.party.includes(state.query)||String(d.id).includes(state.query)).map(d=>`<button class="invoice-row" data-action="any-document" data-kind="${kind}" data-id="${d.id}"><div class="row between"><span class="invoice-number">${docPrefix(d)}-${d.id}</span><span class="status ${kind==='receiving'&&d.status==='waiting'||d.due?'due':''}">${kind==='receiving'?(d.status==='waiting'?'بانتظار فاتورة المورد':'تمت التسوية'):(d.due?'متبقي للمورد':'مدفوعة')}</span></div><div class="party">${esc(d.party)}</div><div class="row between"><span class="amount">${amount(docNet(d))}</span><span class="tiny muted">${esc(d.date)} ${icon('chevron-left')}</span></div></button>`).join('')||emptyView('لا توجد نتائج')}
function buyingListPage(kind='purchase'){return header(kind==='receiving'?'الاستلام السريع':'المشتريات',{back:true,sub:kind==='receiving'?'استلم الآن، وسوِّ التكلفة لاحقًا':'فواتير الموردين والمدفوعات'})+`<main class="app-scroll">${kind==='receiving'?'<div class="welcome-note"><b>وصلت البضاعة قبل الفاتورة؟</b>سجّل الكميات بتكلفة تقديرية، ثم اربط فاتورة المورد عند وصولها.</div>':''}${actionButton(kind==='receiving'?'استلام سريع جديد':'فاتورة شراء جديدة','buy-new','plus',`data-kind="${kind}"`)}${demo.drafts[kind]?`<button class="customer-select" style="margin:14px 0 0" data-action="resume" data-kind="${kind}"><span class="customer-icon">${icon('file-pen-line')}</span><span>متابعة المسودة<small>${demo.drafts[kind].lines.length} منتجات محفوظة في التجربة</small></span>${icon('chevron-left')}</button>`:''}${searchBox('buy-search',state.query,'ابحث بالمورد أو رقم المستند')}<div id="buy-results">${buyingRows(kind)}</div>${demoHint()}</main>`+nav()}
function startBuying(kind='purchase',partyId=null,receipt=null){newInvoice();state.kind=kind;state.customer=partyId;state.payment='credit';state.shipping=0;state.receiptId=receipt?.id||null;if(receipt){state.lines=structuredClone(receipt.items);state.customer=receipt.partyId}navigate('editor')}
function adaptiveCustomerButton(){const p=parties.find(p=>p.id===state.customer);return `<button class="customer-select" data-action="customer" ${state.receiptId?'disabled':''}><span class="customer-icon">${icon(p?'user-round-check':'user-round')}</span><span>${p?esc(p.name):isBuying()?'اختر المورد':'بيع نقدي · بدون عميل'}<small>${p?(state.receiptId?'مرتبط بإذن الاستلام':`اضغط لتغيير ${partyLabel()}`):isBuying()?'المورد مطلوب لاعتماد الشراء':'اختر عميلًا للبيع الآجل أو الدفع الجزئي'}</small></span>${icon('chevron-left')}</button>`}
function advancedEditorPage(){let html=editorPage().replace('فاتورة بيع جديدة',state.receiptId?'فاتورة المورد وتسوية الاستلام':state.kind==='receiving'?'استلام سريع جديد':`${invoiceLabel()} جديدة`);if(state.kind==='receiving')html=html.replaceAll('المراجعة والدفع','مراجعة الاستلام').replace('مراجعة الفاتورة والدفع','مراجعة الاستلام');if(state.receiptId){html=html.replace(/<button class="dashed" data-action="picker">[\s\S]*?<\/button>/,'');html=html.replace(/<div class="quantity-control">[\s\S]*?<\/div>/g,match=>`<span class="small muted">الكمية المستلمة: ${match.match(/<span>([^<]+)<\/span>/)?.[1]||''}</span>`)}return html}
function advancedPaymentPage(){if(state.kind==='receiving')return header('مراجعة الاستلام',{back:true})+stepper(true).replace('المراجعة والدفع','مراجعة الاستلام')+`<main class="app-scroll">${adaptiveCustomerButton()}<section class="panel">${sectionTitle('المنتجات المستلمة')} ${state.lines.map(l=>infoRow(products.find(p=>p.id===l.id).name,`${l.qty} × ${amount(l.price)}`)).join('')}<div class="summary-line total"><span>القيمة التقديرية</span>${amount(subtotal())}</div></section><div class="welcome-note"><b>تكلفة تقديرية</b>يضاف المخزون عند الاعتماد. تُثبت قيمة المورد عند تسوية الاستلام بفاتورته، ولا تُسجَّل دفعة هنا.</div><div id="payment-error" role="alert"></div></main><footer class="action-bar">${actionButton('اعتماد الاستلام','confirm','check')}</footer>`;
 let html=paymentPage().replace(/<select id="account">[\s\S]*?<\/select>/,`<select id="account" aria-label="حساب الدفع">${accounts.map(a=>`<option ${state.account===a.name?'selected':''}>${esc(a.name)}</option>`).join('')}</select>`);if(isBuying()){html=html.replaceAll('آجل','آجل للمورد').replaceAll('المتبقي على العميل','المتبقي للمورد').replaceAll('اعتماد فاتورة البيع','اعتماد فاتورة الشراء').replaceAll('المراجعة والدفع','مراجعة الشراء والدفع');const shipping=`<div class="summary-line"><label for="shipping">الشحن وتكلفة النقل</label><div class="amount-input"><input id="shipping" type="number" min="0" step=".01" inputmode="decimal" value="${(state.shipping||0)/100}"><span>ر.س</span></div></div>`;html=html.replace('<div class="summary-line total">',shipping+'<div class="summary-line total">')}return html}
function adaptiveProductRows(select=true){let list=filteredProducts();return list.map(p=>{let count=state.lines.find(l=>l.id===p.id)?.qty||0;return `<div class="product-row"><span class="item-visual">${icon('package')}</span><div class="product-info"><div class="item-name">${esc(p.name)}</div><small>${esc(p.unit)}${p.service?' · خدمة':` · متوفر ${p.stock}`}</small><div>${amount(isBuying()?p.cost:p.price)}</div></div>${select?`<button class="add-btn ${count?'added':''}" data-action="add" data-id="${p.id}" aria-label="إضافة ${esc(p.name)}">${count?count:icon('plus')}</button>`:''}</div>`}).join('')||emptyView('لا توجد منتجات مطابقة')}
function chooseDemoParty(){const list=parties.filter(p=>p.active&&(isBuying()?p.supplier:p.customer));showSheet(sheetHead(`اختيار ${partyLabel()}`)+`${!isBuying()?'<button class="customer-option" data-action="choose-customer" data-id="0"><span class="avatar">'+icon('banknote')+'</span><span>بيع نقدي<small>بدون عميل</small></span></button>':''}${list.map(c=>`<button class="customer-option" data-action="choose-customer" data-id="${c.id}"><span class="avatar">${esc(c.name[0])}</span><span>${esc(c.name)}<small dir="ltr">${esc(c.phone)}</small></span></button>`).join('')}`)}
function confirmDemoInvoice(){if(isBuying()&&!state.customer){formError('اختر المورد أولًا قبل اعتماد المستند.');return}if(!state.lines.length||state.discount>subtotal()||state.discount<0||(state.shipping||0)<0||state.kind!=='receiving'&&state.payment==='partial'&&(state.paid<=0||state.paid>total())){formError('تحقق من المنتجات والخصم والمبلغ المدفوع.');return}if(state.kind==='sale'&&state.lines.some(l=>{let p=products.find(p=>p.id===l.id);return !p.service&&baseQty(l)>p.stock})){formError('توجد كمية أكبر من المخزون المتاح. راجع كميات المنتجات.');return}showSheet(sheetHead(`اعتماد ${invoiceLabel()}؟`)+`<p class="sheet-help">${state.kind==='receiving'?'ستُضاف الكميات بتكلفة تقديرية.':'راجع المنتجات والطرف والحسابات قبل الاعتماد.'} جميع التغييرات داخل التجربة فقط.</p>${infoRow('الإجمالي',amount(total()))}${state.kind!=='receiving'?infoRow('المدفوع',amount(paid()))+infoRow(`المتبقي ${isBuying()?'للمورد':'على العميل'}`,amount(total()-paid())):''}<div class="button-row"><button class="primary" data-action="post">اعتماد تجريبي</button><button class="secondary" data-action="close-sheet">مراجعة</button></div>`)}
function applyInvoice(){const source=invoiceSet(),p=parties.find(p=>p.id===state.customer),kind=state.kind;const doc={id:Math.max(kind==='sale'?1048:kind==='purchase'?5000:7000,...source.map(d=>d.id))+1,kind,partyId:p?.id,party:p?.name||'بيع نقدي',date:'اليوم، الآن',documentDate:state.date,total:total(),discount:state.discount,shipping:state.shipping||0,due:kind==='receiving'?0:total()-paid(),paid:kind==='receiving'?0:paid(),items:structuredClone(state.lines),status:kind==='receiving'?'waiting':'posted',receiptId:state.receiptId};
 if(kind!=='receiving'){let account=accounts.find(a=>a.name===state.account)||accounts[0];account.balance+=(kind==='sale'?1:-1)*paid()}
 state.lines.forEach(l=>{const p=products.find(p=>p.id===l.id);if(p.service)return;const q=baseQty(l);if(kind!=='sale'&&!state.receiptId){const incoming=Math.round(q*l.price/(l.factor||1));const denominator=p.stock+q;if(denominator>0)p.cost=Math.round((p.stock*p.cost+incoming)/denominator)}if(!state.receiptId){p.stock=Math.round((p.stock+(kind==='sale'?-q:q))*1000)/1000;movements.unshift({productId:p.id,title:`${invoiceLabel()} ${docPrefix(doc)}-${doc.id}`,qty:kind==='sale'?-q:q,cost:p.cost,note:doc.party,date:'الآن'})}p.openingDone=true});
 if(state.receiptId){const r=receipts.find(r=>r.id===state.receiptId);r.status='settled';r.purchaseId=doc.id}
 source.unshift(doc);demo.drafts[kind]=null;state.doc=doc;state.draft=null;state.success=true;state.receiptId=null;sheet.close();logDemo(`اعتماد ${invoiceLabel()} ${docPrefix(doc)}-${doc.id}`);navigate('document')}
function demoDocumentPage(){const d=state.doc,kind=d.kind||'sale',isReceipt=kind==='receiving',net=docNet(d);return header(state.success?'تم اعتماد المستند':'تفاصيل المستند',{back:true,action:`<span class="status ${isReceipt&&d.status==='waiting'||d.due?'due':''}">${isReceipt?(d.status==='waiting'?'بانتظار الفاتورة':'تمت التسوية'):d.due?'متبقي عليها':'مدفوعة'}</span>`})+`<main class="app-scroll">${state.success?`<div class="success-heading"><div class="success-badge">${icon('check')}</div><h2>تمّت، بكل بساطة.</h2><p>تم حفظ المستند داخل التجربة</p></div>`:''}<article class="receipt"><div class="receipt-title"><h3>محل النخبة</h3><p>${isReceipt?'استلام سريع':kind==='purchase'?'فاتورة شراء':'فاتورة بيع'} · <span dir="ltr">${docPrefix(d)}-${d.id}</span></p></div>${infoRow(kind==='sale'?'العميل':'المورد',esc(d.party))}${infoRow('التاريخ',esc(d.documentDate||d.date))}<div style="border-top:1px solid var(--line);margin-top:16px">${d.items.map(l=>`<div class="receipt-line"><span>${esc(products.find(p=>p.id===l.id).name)}<small>${l.qty} × ${money(l.price)} ر.س · ${esc(l.unit)}</small></span>${amount(Math.round(l.qty*l.price))}</div>`).join('')}</div><div class="receipt-footer">${d.discount?infoRow('خصم الفاتورة',amount(d.discount)):''}${d.shipping?infoRow('الشحن',amount(d.shipping)):''}${d.returned?infoRow('مردودات معتمدة',amount(d.returned)):''}<div class="summary-line total"><span>${isReceipt?'القيمة التقديرية':(d.returned?'الصافي بعد المرتجعات':'الإجمالي')}</span>${amount(net)}</div>${!isReceipt?infoRow('المدفوع',amount(Math.max(0,net-d.due)))+infoRow('المتبقي',amount(d.due)):''}</div></article>${isReceipt?`<div class="welcome-note">${d.status==='waiting'?'الكمية أُضيفت إلى المخزون بتكلفة تقديرية. عند وصول الفاتورة، راجع تكلفة المورد وسوِّ الاستلام.':'تم ربط فاتورة المورد؛ لا يضاف المخزون مرة ثانية.'}</div>`:''}${demoHint()}</main><footer class="action-bar">${isReceipt&&d.status==='waiting'?actionButton('تسوية بفاتورة المورد','finalize-receipt','file-check-2'):`<div class="button-row"><button class="secondary" data-action="print">${icon('printer')} طباعة</button>${!isReceipt?actionButton('إرجاع منتجات','return-new','undo-2'):''}</div>`}${state.success?'<button class="text-button full" data-action="document-list">العودة إلى القائمة</button>':''}</footer>`}
function newFinance(kind='receipt',partyId=null){demo.financeKind=kind;demo.form={kind,partyId:partyId||'',amount:'',account:'cash',toAccount:'bank',category:'تشغيل المحل',note:''};goDemo('finance-form')}
function operationRow(o){const incoming=['receipt','capital'].includes(o.kind);return `<button class="ledger-row" data-action="operation-detail" data-id="${o.id}"><span class="transaction-icon ${incoming?'in':'out'}">${icon(o.kind==='transfer'?'arrow-left-right':incoming?'arrow-down-left':'arrow-up-right')}</span><div class="record-body"><b>${esc(o.party||o.note||o.label)}</b><small>${o.label} · ${esc(o.date)}</small></div><span class="ledger-amount ${incoming?'positive':''}">${amount(o.amount)}</span></button>`}
function financeOverviewPage(){return header('المالية',{sub:'أرصدة المحل وحركته اليومية'})+`<main class="app-scroll"><section class="sales-summary"><span class="small">إجمالي النقد والبنوك</span><div class="summary-number">${amount(accounts.reduce((n,a)=>n+a.balance,0))}</div><div class="summary-bottom"><span>${accounts.length} حسابات</span><span>أرصدة توضيحية</span></div></section><div class="quick-actions"><button class="quick-action" data-action="finance-new" data-kind="receipt">${icon('arrow-down-left')}قبض من عميل</button><button class="quick-action" data-action="finance-new" data-kind="payment">${icon('arrow-up-right')}سداد مورد</button><button class="quick-action" data-action="finance-new" data-kind="expense">${icon('receipt')}مصروف</button><button class="quick-action" data-action="finance-types">${icon('plus')}عملية أخرى</button></div>${sectionTitle('الحسابات',`<button class="text-button" data-action="account-new">إضافة حساب</button>`)}<div class="account-list">${accounts.map(a=>`<button class="account-row" data-action="account-detail" data-value="${a.id}"><span class="customer-icon">${icon(a.type==='bank'?'landmark':'banknote')}</span><span>${esc(a.name)}<small>${a.type==='bank'?'حساب بنكي':'حساب نقدي'}</small></span><b>${amount(a.balance)}</b></button>`).join('')}</div><div style="margin-top:24px">${sectionTitle('آخر العمليات')}${operations.map(operationRow).join('')}</div>${demoHint()}</main>`+nav()}
function allocationPreview(){const v=demo.form;if(!['receipt','payment'].includes(v.kind)||!v.partyId)return '';let p=parties.find(p=>p.id===Number(v.partyId)),source=v.kind==='receipt'?documents:purchases,remaining=Math.round(Number(v.amount||0)*100);const rows=[];for(const d of [...source].reverse().filter(d=>(d.partyId===p.id||d.party===p.name)&&d.due>0)){const allocated=Math.min(d.due,Math.max(0,remaining));remaining-=allocated;rows.push(infoRow(`${docPrefix(d)}-${d.id}`,amount(allocated)))}return `<section class="panel">${sectionTitle('تخصيص الدفعة')}<p class="tiny muted">تُسدّد أقدم الفواتير أولًا، ويُحفظ الفائض رصيدًا مقدمًا.</p>${rows.join('')||'<p class="small muted">لا توجد فواتير مستحقة.</p>'}${remaining>0?infoRow('دفعة مقدمة',amount(remaining)):''}</section>`}
function financeFormPage(){const v=demo.form,kind=v.kind,partyItems=parties.filter(p=>p.active&&(kind==='receipt'?p.customer:p.supplier));return formPage(opLabels[kind],`<section class="panel">${selectField('نوع العملية','kind',kind,Object.entries(opLabels))}${['receipt','payment'].includes(kind)?selectField(kind==='receipt'?'العميل':'المورد','partyId',v.partyId,[['','اختر الطرف'],...partyItems.map(p=>[p.id,p.name])]):''}${kind==='expense'?formField('تصنيف المصروف','category',v.category,{required:true}):''}${formField('المبلغ (ر.س)','amount',v.amount,{type:'number',min:'.01',step:'.01',required:true})}${selectField(kind==='transfer'?'الحساب المحوِّل':'الحساب','account',v.account,accounts.map(a=>[a.id,a.name]))}${kind==='transfer'?selectField('الحساب المستلم','toAccount',v.toAccount,accounts.map(a=>[a.id,a.name])):''}${formField('البيان (اختياري)','note',v.note)}</section><div id="allocation-preview">${allocationPreview()}</div>${demoHint('ستظهر مراجعة نهائية قبل اعتماد العملية. لا تُنفّذ هذه المعاينة تحويلات أو مدفوعات حقيقية.')}`,'finance-form','مراجعة العملية')}
function reviewFinance(){const v=demo.form,amountValue=Math.round(Number(v.amount)*100);if(!Number.isFinite(amountValue)||amountValue<=0){formError('أدخل مبلغًا أكبر من صفر.');return}if(['receipt','payment'].includes(v.kind)&&!v.partyId){formError('اختر الطرف أولًا.');return}if(v.kind==='transfer'&&v.account===v.toAccount){formError('اختر حسابين مختلفين للتحويل.');return}showSheet(sheetHead('مراجعة العملية')+infoRow('العملية',opLabels[v.kind])+infoRow('المبلغ',amount(amountValue))+infoRow('الحساب',esc(accounts.find(a=>a.id===v.account).name))+(v.kind==='transfer'?infoRow('الحساب المستلم',esc(accounts.find(a=>a.id===v.toAccount).name)):'')+(v.partyId?infoRow('الطرف',esc(parties.find(p=>p.id===Number(v.partyId)).name)):'')+`<div class="button-row"><button class="primary" data-action="finance-post">اعتماد تجريبي</button><button class="secondary" data-action="close-sheet">مراجعة</button></div>`)}
function postFinance(){const v=demo.form,n=Math.round(Number(v.amount)*100),a=accounts.find(a=>a.id===v.account),incoming=['receipt','capital'].includes(v.kind);a.balance+=incoming?n:-n;if(v.kind==='transfer')accounts.find(a=>a.id===v.toAccount).balance+=n;const party=parties.find(p=>p.id===Number(v.partyId));if(party&&['receipt','payment'].includes(v.kind)){const source=v.kind==='receipt'?documents:purchases;let remaining=n;for(const d of [...source].reverse().filter(d=>d.partyId===party.id||d.party===party.name)){const allocated=Math.min(d.due,remaining);d.due-=allocated;remaining-=allocated}const key=v.kind==='receipt'?'customerAdvance':'supplierAdvance';party[key]=(party[key]||0)+remaining}
const o={id:Math.max(100,...operations.map(o=>o.id))+1,kind:v.kind,label:opLabels[v.kind],partyId:party?.id,party:party?.name,amount:n,account:a.id,toAccount:v.toAccount,date:'الآن',note:v.note||v.category||opLabels[v.kind]};operations.unshift(o);demo.operationId=o.id;sheet.close();logDemo(`اعتماد ${o.label}`);goDemo('operation-detail');toast('تم اعتماد العملية داخل التجربة')}
function operationDetailPage(){const o=operations.find(o=>o.id===demo.operationId);return header('تفاصيل العملية',{back:true})+`<main class="app-scroll"><div class="entity-heading"><span class="entity-icon">${icon('wallet')}</span><h2>${o.label}</h2><p><span dir="ltr">FIN-${o.id}</span> · ${esc(o.date)}</p></div><article class="receipt"><div class="summary-line total"><span>المبلغ</span>${amount(o.amount)}</div>${infoRow('الحساب',esc(accounts.find(a=>a.id===o.account)?.name||'—'))}${o.kind==='transfer'?infoRow('إلى حساب',esc(accounts.find(a=>a.id===o.toAccount)?.name||'—')):''}${o.party?infoRow('الطرف',esc(o.party)):''}${infoRow('البيان',esc(o.note))}<span class="status">معتمدة في التجربة</span></article>${demoHint()}</main><footer class="action-bar"><button class="secondary full" data-action="print">${icon('printer')} طباعة المستند</button></footer>`}
function returnValue(){const d=demo.returnDoc,base=d.items.reduce((n,l)=>n+Math.round(l.qty*l.price),0),gross=d.items.reduce((n,l)=>n+Number(demo.form[`return-${l.id}`]||0)*l.price,0);return Math.round(gross*(1-(d.discount||0)/(base||1)))}
function returnPage(){const d=demo.returnDoc;return formPage('إرجاع منتجات',`<div class="welcome-note"><b>${docPrefix(d)}-${d.id} · ${esc(d.party)}</b>أدخل الكمية المراد إرجاعها من كل منتج. تُخفض المبالغ غير المسددة أولًا.</div>${d.items.map(l=>{let available=l.qty-(l.returned||0);return `<section class="panel">${sectionTitle(esc(products.find(p=>p.id===l.id).name))}<p class="tiny muted" style="margin-bottom:12px">متاح للإرجاع ${available} ${esc(l.unit)}</p>${formField('كمية الإرجاع',`return-${l.id}`,demo.form[`return-${l.id}`]||0,{type:'number',min:0,max:available,step:'.001'})}</section>`}).join('')}<section class="panel">${selectField('التعامل مع المبلغ الزائد عن المستحق','refundMode',demo.form.refundMode,[['cash','رد المبلغ من / إلى حساب'],...(d.partyId||d.party!=='بيع نقدي'?[['credit','إبقاؤه دفعة مقدمة للطرف']]:[])])}${demo.form.refundMode==='cash'?selectField('حساب الرد','refundAccount',demo.form.refundAccount,accounts.map(a=>[a.id,a.name])):''}<div class="summary-line total"><span>قيمة المرتجع</span><span id="return-value">${amount(returnValue())}</span></div></section>${demoHint()}`,'return-form','مراجعة المرتجع')}
function reviewReturn(){const d=demo.returnDoc,value=returnValue();if(value<=0){formError('أدخل كمية واحدة على الأقل للإرجاع.');return}if(d.items.some(l=>Number(demo.form[`return-${l.id}`]||0)<0||Number(demo.form[`return-${l.id}`]||0)>l.qty-(l.returned||0))){formError('كمية الإرجاع تتجاوز الكمية المتبقية.');return}showSheet(sheetHead('مراجعة المرتجع')+infoRow('قيمة المرتجع',amount(value))+infoRow('تخفيض غير المسدد',amount(Math.min(d.due,value)))+infoRow(demo.form.refundMode==='credit'?'دفعة مقدمة للطرف':'المبلغ المسترد',amount(Math.max(0,value-d.due)))+`<div class="button-row"><button class="primary" data-action="return-post">اعتماد المرتجع</button><button class="secondary" data-action="close-sheet">مراجعة</button></div>`)}
function postReturn(){const d=demo.returnDoc,v=returnValue(),refund=Math.max(0,v-d.due),purchase=d.kind==='purchase';if(purchase&&d.items.some(l=>{const p=products.find(p=>p.id===l.id);return !p.service&&Number(demo.form[`return-${l.id}`]||0)*(l.factor||1)>p.stock})){sheet.close();formError('المخزون الحالي غير كافٍ لإرجاع هذه الكمية إلى المورد.');return}d.due=Math.max(0,d.due-v);d.returned=(d.returned||0)+v;d.items.forEach(l=>{const q=Number(demo.form[`return-${l.id}`]||0),p=products.find(p=>p.id===l.id);l.returned=(l.returned||0)+q;if(!p.service&&q){p.stock+=q*(l.factor||1)*(purchase?-1:1);movements.unshift({productId:p.id,title:`مرتجع ${docPrefix(d)}-${d.id}`,qty:q*(l.factor||1)*(purchase?-1:1),note:d.party,date:'الآن'})}});if(refund){if(demo.form.refundMode==='cash')accounts.find(a=>a.id===demo.form.refundAccount).balance+=purchase?refund:-refund;else{const p=parties.find(p=>p.id===d.partyId||p.name===d.party);if(p){const key=purchase?'supplierAdvance':'customerAdvance';p[key]=(p[key]||0)+refund}}}sheet.close();state.doc=d;state.success=false;logDemo(`مرتجع ${docPrefix(d)}-${d.id}`);navigate('document');toast('تم اعتماد المرتجع داخل التجربة')}
const trialSample=[{code:'1101',name:'الصندوق الرئيسي',debit:1245000,credit:0},{code:'1102',name:'حساب الراجحي',debit:2860000,credit:0},{code:'1201',name:'المخزون',debit:500000,credit:0},{code:'1301',name:'ذمم العملاء',debit:53500,credit:0},{code:'2101',name:'ذمم الموردين',debit:0,credit:90000},{code:'3101',name:'رأس المال',debit:0,credit:4497600},{code:'4101',name:'المبيعات',debit:0,credit:100900},{code:'5101',name:'المصروفات',debit:30000,credit:0}];
function reportsPageDemo(){const sales=documents.filter(d=>demo.reportPeriod!=='today'||d.date.startsWith('اليوم')),sum=sales.reduce((n,d)=>n+docNet(d),0),cost=sales.reduce((n,d)=>n+d.items.reduce((n,l)=>n+Math.round((l.qty-(l.returned||0))*products.find(p=>p.id===l.id).cost*(l.factor||1)),0),0);return header('التقارير والمحاسبة',{back:true,action:`<button class="icon-btn" data-action="print" aria-label="طباعة التقرير">${icon('printer')}</button>`})+`<main class="app-scroll">${dataChips([['today','اليوم'],['month','كل البيانات']],demo.reportPeriod,'report-period')}<section class="sales-summary"><span class="small">صافي المبيعات ${demo.reportPeriod==='today'?'اليوم':''}</span><div class="summary-number">${amount(sum)}</div><div class="summary-bottom"><span>${sales.length} فواتير</span><span>بعد المردودات</span></div></section><div class="metrics-pair"><div><span>مجمل الربح التقديري</span><strong>${amount(sum-cost)}</strong></div><div><span>غير المسدد</span><strong>${amount(sales.reduce((n,d)=>n+d.due,0))}</strong></div></div><p class="tiny muted">الربح للمعاينة، حسب تكلفة الوحدة الحالية. لا يمثل إقفالًا محاسبيًا.</p>${dataChips([['trial','ميزان المراجعة'],['sales','فواتير المبيعات']],demo.reportTab,'report-tab')}${demo.reportTab==='trial'?`<div class="welcome-note"><b>مثال لعرض ميزان المراجعة</b>الأرقام التالية ثابتة لتوضيح التصميم. افتح الحساب لعرض دفتر الأستاذ.</div><div class="trial-header"><span>الحساب</span><span>مدين / دائن</span></div>${trialSample.map(t=>`<button class="ledger-row" data-action="ledger" data-value="${t.code}"><div class="record-body"><b>${t.name}</b><small>${t.code}</small></div><div class="ledger-amount">${amount(t.debit||t.credit)}<small>${t.debit?'مدين':'دائن'}</small></div>${icon('chevron-left')}</button>`).join('')}<section class="panel" style="margin-top:15px">${infoRow('إجمالي المدين',amount(trialSample.reduce((n,t)=>n+t.debit,0)))}${infoRow('إجمالي الدائن',amount(trialSample.reduce((n,t)=>n+t.credit,0)))}</section>`:sales.map(invoiceRow).join('')}${demoHint()}</main>`}
function ledgerPage(){const a=trialSample.find(t=>t.code===demo.ledger);return header('دفتر الأستاذ',{back:true,sub:`${a.code} · ${a.name}`})+`<main class="app-scroll"><section class="stock-hero"><span class="small muted">رصيد الحساب · مثال توضيحي</span><div><strong>${amount(a.debit||a.credit)}</strong></div><span class="status">${a.debit?'مدين':'دائن'}</span></section>${sectionTitle('تفاصيل الحركة')}<div class="panel">${infoRow('رصيد افتتاحي',amount((a.debit||a.credit)-10000))}${infoRow('حركة خلال الفترة',amount(10000))}${infoRow('الرصيد النهائي',amount(a.debit||a.credit))}</div><p class="small muted">يعرض هذا المثال ترتيب البيانات على الجوال. تتصل القيود الفعلية بالمستندات عند تنفيذ الواجهة في التطبيق.</p></main>`}
function settingsPageDemo(){return header('الإعدادات',{back:true})+`<main class="app-scroll"><div class="customer-select"><span class="avatar">${esc((demoShop.fullName||'عبدالله')[0])}</span><span>${esc(demoShop.name)}<small>إدارة بيانات المحل وتفضيلات العمل</small></span></div>${[['store-settings','store','بيانات المحل','الاسم والعنوان ومعلومات التواصل'],['profile','user-round','ملفي الشخصي','اسم المستخدم وكلمة المرور'],['users','users-round','المستخدمون والصلاحيات',`${users.length} مستخدمين في المحل`],['backups','database-backup','النسخ الاحتياطي والاستعادة','نسخ تجريبية داخل المعاينة'],['audit','list-checks','سجل العمليات','الحركات التي أجريتها في التجربة']].map(([v,i,t,sub])=>`<button class="customer-select" data-action="settings-link" data-view="${v}"><span class="customer-icon">${icon(i)}</span><span>${t}<small>${sub}</small></span>${icon('chevron-left')}</button>`).join('')}<section class="panel">${sectionTitle('تفضيلات العمل')}${checkField('تفعيل نقطة البيع السريعة','pos',demo.pos,'إظهار اختصار نقطة البيع في المزيد')}</section><p class="list-note">دبت للحسابات · نموذج تصميم تفاعلي</p></main>`}
