function profilePageDemo(){return header('ملفي الشخصي',{back:true})+`<main class="app-scroll"><div class="entity-heading"><span class="entity-icon">${icon('user-round')}</span><h2>${esc(demoShop.fullName||'عبدالله محمد')}</h2><p>المالك · ${esc(demoShop.name)}</p></div><form id="profile-form"><section class="panel">${sectionTitle('معلومات الدخول')}${formField('اسم المستخدم','username',demoShop.username,{required:true})}<button class="secondary full" type="button" data-action="password">${icon('key-round')} تغيير كلمة المرور</button></section></form>${demoHint('الاسم الكامل وبيانات المحل متاحة في إعدادات المحل.')}</main><footer class="action-bar"><button class="primary full" type="submit" form="profile-form">حفظ التغييرات</button></footer>`}
