function backupsPage(){return header('النسخ الاحتياطي',{back:true})+`<main class="app-scroll"><div class="backup-health">${icon('shield-check')}<div><h3>${demo.backups.length?'لديك نسخة تجريبية':'احفظ نسخة من التجربة'}</h3><p>النسخ هنا في الذاكرة، وتختفي عند تحديث الصفحة.</p></div></div><section class="panel">${checkField('النسخ التلقائي','backupAuto',demo.backupAuto,'معاينة لتفضيل النسخ اليومي؛ لا يشغّل خدمة نسخ فعلية')}${demoHint('عند تنفيذ التطبيق، تعرض هذه المساحة حالة آخر نسخة ومكان حفظها.')}</section>${actionButton('إنشاء نسخة تجريبية الآن','backup-create','database-backup')}<div style="margin-top:24px">${sectionTitle('نسخ هذه التجربة')}${demo.backups.length?demo.backups.map(b=>`<button class="record-row" data-action="backup-restore" data-id="${b.id}"><span class="item-visual">${icon('archive')}</span><div class="record-body"><b>نسخة ${b.id}</b><small>${b.date} · ${b.snapshot.products.length} منتجات</small></div><span class="text-button">استعادة</span></button>`).join(''):emptyView('لا توجد نسخ بعد','أنشئ نسخة، ثم غيّر بعض البيانات وجرّب استعادتها.')}</div></main>`}
