function expandedMorePage(){return header('المزيد',{sub:'كل ما تحتاجه لإدارة محلك'})+`<main class="app-scroll"><button class="customer-select" data-action="profile"><span class="avatar">${esc((demoShop.fullName||'عبدالله')[0])}</span><span>${esc(demoShop.fullName||'عبدالله محمد')}<small>مالك المحل · ${esc(demoShop.name)}</small></span>${icon('chevron-left')}</button>${[['parties','users-round','العملاء والموردون'],['purchases','shopping-bag','المشتريات'],['stock','boxes','المخزون والاستلام'],['receiving','truck','الاستلام السريع'],['reports','chart-no-axes-combined','التقارير والمحاسبة'],['settings','settings-2','الإعدادات والنسخ']].map(([v,i,t])=>`<button class="more-row" data-action="more-link" data-view="${v}">${icon(i)}${t}${icon('chevron-left')}</button>`).join('')}${demo.pos?'<button class="more-row" data-action="pos">'+icon('scan-line')+'نقطة البيع السريعة'+icon('chevron-left')+'</button>':''}<div class="welcome-note" style="margin-top:24px"><b>تجربة واحدة مترابطة</b>جرّب إنشاء منتج وشراء كمية منه، ثم بيعه ومتابعة المخزون وحساب الطرف.</div><button class="secondary full" data-action="reset">${icon('rotate-ccw')} إعادة التجربة من البداية</button></main>`+nav()}
function snapshotDemo(){return structuredClone({products,parties,documents,purchases,receipts,accounts,movements,operations,users,shop:demoShop,categories,units})}
function restoreDemo(s){for(const [key,target]of Object.entries({products,parties,documents,purchases,receipts,accounts,movements,operations,users,categories,units}))target.splice(0,target.length,...structuredClone(s[key]));Object.assign(demoShop,s.shop);state.lines=[];demo.drafts={sale:null,purchase:null,receiving:null};state.draft=null;state.customer=null;state.doc=null;state.receiptId=null;state.shipping=0;state.kind='sale'}
function handleFeatureAction(b){const a=b.dataset.action,id=Number(b.dataset.id),value=b.dataset.value;
 switch(a){
 case 'nav':demo.query='';if(b.dataset.view==='sales'){state.kind='sale';state.shipping=0;state.draft=demo.drafts.sale}goDemo(b.dataset.view);return true;
 case 'more-link':demo.query='';goDemo(b.dataset.view);return true;
 case 'settings-link':if(b.dataset.view==='store-settings')demo.form={...demoShop};goDemo(b.dataset.view);return true;
 case 'profile':goDemo('profile');return true;
 case 'preview':state.kind='sale';state.shipping=0;return false;
 case 'new':state.kind='sale';state.shipping=0;state.draft=demo.drafts.sale;return false;
 case 'resume':{const draft=demo.drafts[b.dataset.kind||'sale'];if(draft){state.draft=draft;Object.assign(state,structuredClone(draft));sheet.close();navigate('editor')}return true}
 case 'product-new':newProduct();return true;
 case 'product-detail':demo.productId=id;goDemo('product-detail');return true;
 case 'product-edit':newProduct(demo.productId);return true;
 case 'catalog-filter':demo.productFilter=value;render();return true;
 case 'references':showSheet(sheetHead('التصنيفات والوحدات')+`<p class="sheet-help">تُستخدم القوائم نفسها عند إضافة المنتجات أو تعديلها.</p><button class="more-row" data-action="reference-list" data-value="categories">${icon('tags')}التصنيفات${icon('chevron-left')}</button><button class="more-row" data-action="reference-list" data-value="units">${icon('ruler')}الوحدات${icon('chevron-left')}</button>`);return true;
 case 'reference-list':demo.referenceType=value;sheet.close();showSheet(sheetHead(value==='categories'?'التصنيفات':'الوحدات')+`<div class="reference-list">${(value==='categories'?categories:units).map(t=>`<div class="reference-row">${esc(t)}</div>`).join('')}</div><form id="reference-form"><label class="field">إضافة ${value==='categories'?'تصنيف':'وحدة'}<input name="name" required maxlength="70"></label><button class="primary full" type="submit">إضافة</button></form>`);return true;
 case 'opening':demo.form={quantity:''};goDemo('opening');return true;
 case 'stock-filter':demo.inventoryFilter=value;render();return true;
 case 'inventory-detail':demo.productId=id;demo.stockOrigin='stock';goDemo('inventory-detail');return true;
 case 'product-inventory':demo.stockOrigin='product-detail';goDemo('inventory-detail');return true;
 case 'receiving-list':goDemo('receiving');return true;
 case 'adjust-stock':{const p=getProduct();showSheet(sheetHead('جرد وتسوية المخزون')+`<p class="sheet-help">${esc(p.name)} · المتاح حاليًا ${p.stock} ${esc(p.unit)}. أدخل الكمية الفعلية المتبقية.</p><form id="adjust-form">${formField('الكمية الفعلية بعد الجرد','quantity','',{type:'number',min:0,step:'.001',required:true})}${formField('تكلفة الوحدات الزائدة (اختياري)','cost','',{type:'number',min:0,step:'.01'})}${formField('سبب التسوية','reason','',{required:true})}${checkField('تسوية تالف','damaged',false)}<button class="primary full" type="submit">مراجعة التسوية</button></form>`);return true}
 case 'adjust-post':{const p=getProduct(),v=demo.adjustment,delta=Math.round((v.quantity-p.stock)*1000)/1000;if(delta>0&&v.cost!==null)p.cost=Math.round((p.stock*p.cost+delta*v.cost)/v.quantity);p.stock=v.quantity;p.openingDone=true;movements.unshift({productId:p.id,title:v.damaged?'تسوية تالف':'تسوية جرد',qty:delta,note:v.reason,date:'الآن'});sheet.close();logDemo(`تسوية مخزون ${p.name}`);render();toast('تم اعتماد تسوية المخزون');return true}
 case 'party-filter':demo.partyFilter=value;render();return true;
 case 'party-new':newParty();return true;
 case 'party-detail':demo.partyId=id;demo.partyRole=demo.partyFilter;goDemo('party-detail');return true;
 case 'party-edit':newParty(demo.partyId);return true;
 case 'party-statement-role':demo.partyRole=value;render();return true;
 case 'party-voucher':newFinance(demo.partyRole==='supplier'?'payment':'receipt',demo.partyId);return true;
 case 'party-invoice':if(demo.partyRole==='supplier')startBuying('purchase',demo.partyId);else{newInvoice();state.customer=demo.partyId;render()}return true;
 case 'buy-new':startBuying(b.dataset.kind);return true;
 case 'document':state.kind='sale';return false;
 case 'any-document':{const source=b.dataset.kind==='purchase'?purchases:b.dataset.kind==='receiving'?receipts:documents;state.doc=source.find(d=>d.id===id);state.kind=b.dataset.kind;state.success=false;navigate('document');return true}
 case 'customer':chooseDemoParty();return true;
 case 'choose-customer':state.customer=id||null;if(!state.customer)state.payment='cash';sheet.close();render();return true;
 case 'confirm':confirmDemoInvoice();return true;
 case 'post':applyInvoice();return true;
 case 'document-list':navigate((state.doc.kind||'sale')==='sale'?'sales':state.doc.kind==='receiving'?'receiving':'purchases');return true;
 case 'finalize-receipt':startBuying('purchase',state.doc.partyId,state.doc);return true;
 case 'return-new':demo.returnDoc=state.doc;demo.form={refundMode:'cash',refundAccount:'cash'};goDemo('return');return true;
 case 'return-post':postReturn();return true;
 case 'edit':{editLine(id);if(state.receiptId){const input=sheet.querySelector('[name="qty"]');input.readOnly=true;input.setAttribute('aria-readonly','true');sheet.querySelector('[data-action="remove"]').hidden=true}const l=state.lines.find(l=>l.id===id),p=products.find(p=>p.id===id),select=sheet.querySelector('[name="unit"]');if(p.alternateUnit&&!state.receiptId){select.innerHTML=[p.unit,p.alternateUnit].map(u=>`<option ${u===l.unit?'selected':''}>${esc(u)}</option>`).join('')}return true}
 case 'finance-new':newFinance(b.dataset.kind);return true;
 case 'finance-types':showSheet(sheetHead('عملية مالية جديدة')+Object.entries(opLabels).map(([key,label])=>`<button class="more-row" data-action="finance-kind" data-kind="${key}">${icon(key==='transfer'?'arrow-left-right':'wallet')}${label}${icon('chevron-left')}</button>`).join(''));return true;
 case 'finance-kind':sheet.close();newFinance(b.dataset.kind);return true;
 case 'finance-post':postFinance();return true;
 case 'operation-detail':demo.operationId=id;goDemo('operation-detail');return true;
 case 'account-new':showSheet(sheetHead('حساب جديد')+`<form id="account-form">${formField('اسم الحساب','name','',{required:true})}${selectField('نوع الحساب','type','cash',[['cash','نقدي'],['bank','بنك']])}<p class="sheet-help">يُنشأ الحساب برصيد صفر. تُسجّل الأرصدة الافتتاحية ضمن إعداد المحاسبة في التطبيق.</p><button class="primary full" type="submit">إضافة الحساب</button></form>`);return true;
 case 'account-detail':{const account=accounts.find(a=>a.id===value);showSheet(sheetHead(esc(account.name))+`<div class="summary-line total"><span>الرصيد</span>${amount(account.balance)}</div><p class="small muted" style="margin-top:20px">العمليات المالية المسجلة</p>${operations.filter(o=>o.account===value||o.kind==='transfer'&&o.toAccount===value).map(o=>infoRow(o.label,amount(o.amount))).join('')||'<p class="small muted">لا توجد سندات في هذه التجربة.</p>'}`);return true}
 case 'report-period':demo.reportPeriod=value;render();return true;
 case 'report-tab':demo.reportTab=value;render();return true;
 case 'ledger':demo.ledger=value;goDemo('ledger');return true;
 case 'user-new':editUser();return true;
 case 'user-edit':editUser(id);return true;
 case 'password':showSheet(sheetHead('تغيير كلمة المرور')+`<p class="sheet-help">نموذج لتجربة الواجهة؛ لا يغيّر معلومات الدخول الفعلية.</p><form id="password-form">${formField('كلمة المرور الجديدة','password','',{type:'password',required:true})}${formField('تأكيد كلمة المرور','confirm','',{type:'password',required:true})}<div id="password-error" role="alert"></div><button class="primary full" type="submit">حفظ كلمة المرور</button></form>`);return true;
 case 'backup-create':demo.backups.unshift({id:demo.backups.length+1,date:new Date().toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'}),snapshot:snapshotDemo()});logDemo('إنشاء نسخة تجريبية');render();toast('تم حفظ نسخة في ذاكرة هذه التجربة');return true;
 case 'backup-restore':demo.restoreId=id;showSheet(sheetHead('استعادة النسخة التجريبية؟')+`<p class="sheet-help">ستعود بيانات المعاينة إلى النسخة ${id}، وتُستبدل التغييرات التي أجريتها بعدها. لا تتأثر بيانات التطبيق الفعلي.</p><div class="button-row"><button class="primary" data-action="restore-post">استعادة النسخة</button><button class="secondary" data-action="close-sheet">رجوع</button></div>`);return true;
 case 'restore-post':restoreDemo(demo.backups.find(b=>b.id===demo.restoreId).snapshot);sheet.close();logDemo('استعادة نسخة تجريبية');goDemo('backups');toast('تمت استعادة بيانات المعاينة');return true;
 case 'pos':newInvoice();navigate('picker');return true;
 case 'back':{const parents={'product-detail':'products','product-form':demo.productId?'product-detail':'products',opening:'product-detail','inventory-detail':demo.stockOrigin,'party-detail':'parties','party-form':demo.partyId?'party-detail':'parties','finance-form':'finance','operation-detail':'finance',return:'document',ledger:'reports','store-settings':'settings',profile:'settings',users:'settings',backups:'settings',audit:'settings',settings:'more',reports:'more',purchases:'more',receiving:'stock',stock:'more',parties:'more'};if(state.view==='document'){state.success=false;navigate((state.doc.kind||'sale')==='sale'?'sales':state.doc.kind==='receiving'?'receiving':'purchases');return true}if(state.view==='editor'){saveDraft();navigate(invoiceList());return true}if(parents[state.view]){goDemo(parents[state.view]);return true}return false}
 default:return false;
 }
}
function editUser(id=null){demo.userId=id;const u=users.find(u=>u.id===id)||{name:'',username:'',role:'seller',active:true};showSheet(sheetHead(id?'تعديل المستخدم':'مستخدم جديد')+`<form id="user-form">${formField('الاسم','name',u.name,{required:true})}${formField('اسم المستخدم','username',u.username,{required:true})}${selectField('الدور','role',u.role,Object.entries(roleLabels).filter(([key])=>key!=='owner'||u.role==='owner'))}${formField('حد الخصم ٪','discount',u.discount||0,{type:'number',min:0,max:100})}${checkField('السماح بتغيير سعر البيع','changePrice',u.changePrice||false)}${checkField('المستخدم نشط','active',u.active)}<button class="primary full" type="submit">حفظ المستخدم</button></form>`)}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.field)demo.form[t.dataset.field]=t.type==='checkbox'?t.checked:t.value;
 const searches={'catalog-search':()=>{state.productQuery=t.value;document.querySelector('#catalog-results').innerHTML=catalogRows()},'stock-search':()=>{demo.query=t.value;document.querySelector('#stock-results').innerHTML=stockRows()},'party-search':()=>{demo.query=t.value;document.querySelector('#party-results').innerHTML=partyRows()},'buy-search':()=>{state.query=t.value;document.querySelector('#buy-results').innerHTML=buyingRows(state.view==='receiving'?'receiving':'purchase')}};if(searches[t.id]){searches[t.id]();icons()}
 if(t.id==='shipping'){state.shipping=Math.round(Number(t.value||0)*100);document.querySelector('#payment-total').innerHTML=amount(total());document.querySelector('#footer-total').innerHTML=amount(total());document.querySelector('#balances').innerHTML=balances()}
 if(state.view==='opening'&&t.name==='quantity')document.querySelector('#opening-value').innerHTML=amount(Math.round(Number(t.value||0)*getProduct().cost));
 if(state.view==='finance-form'&&t.name==='amount'){document.querySelector('#allocation-preview').innerHTML=allocationPreview()}
 if(state.view==='return'&&t.name.startsWith('return-'))document.querySelector('#return-value').innerHTML=amount(returnValue());
 if(t.dataset.field==='pos'){demo.pos=t.checked;toast('تم تحديث تفضيل نقطة البيع في التجربة')}
 if(t.dataset.field==='backupAuto'){demo.backupAuto=t.checked;toast('تم تحديث تفضيل النسخ في التجربة')}
});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.field)demo.form[t.dataset.field]=t.type==='checkbox'?t.checked:t.value;
 if(state.view==='product-form'&&['service','alternateUnit','unit'].includes(t.name)){demo.form.service=demo.form.service===true||demo.form.service==='true';if(t.name==='unit'&&demo.form.alternateUnit===t.value)demo.form.alternateUnit='';render.keepScroll=true;render()}
 if(state.view==='finance-form'&&t.name==='kind'){demo.financeKind=t.value;demo.form.partyId='';render.keepScroll=true;render()}
 if(state.view==='finance-form'&&t.name==='partyId')document.querySelector('#allocation-preview').innerHTML=allocationPreview();
 if(state.view==='return'&&t.name==='refundMode'){render.keepScroll=true;render()}
 if(t.closest('#edit-form')&&t.name==='unit'){const l=state.lines.find(l=>l.id===Number(t.closest('form').dataset.id)),p=products.find(p=>p.id===l.id),factor=t.value===p.unit?1:p.factor;const price=(isBuying()?p.cost:p.price)*factor;t.closest('form').elements.price.value=price/100;document.querySelector('#edit-total').innerHTML=amount(Math.round(Number(t.closest('form').elements.qty.value)*price))}
});
document.addEventListener('submit',e=>{const form=e.target,id=form.id,data=new FormData(form),v=Object.fromEntries(data);if(!['product-form','opening-form','party-form','adjust-form','finance-form','return-form','reference-form','account-form','store-form','profile-form','password-form','user-form'].includes(id))return;e.preventDefault();
 switch(id){
 case 'product-form':{if(v.alternateUnit&&v.alternateUnit===v.unit){formError('اختر وحدة إضافية مختلفة عن الوحدة الأساسية.');return}let p=getProduct(),isNew=!p;if(isNew){p={id:Math.max(...products.map(p=>p.id))+1,stock:0,openingDone:false};products.push(p)}Object.assign(p,{name:v.name.trim(),code:v.code.trim(),category:v.category,unit:v.unit,price:Math.round(Number(v.price)*100),cost:Math.round(Number(v.cost||0)*100),minStock:Number(v.minStock||0),active:data.has('active'),service:v.service==='true',alternateUnit:v.alternateUnit||'',factor:Number(v.factor||1)});demo.productId=p.id;logDemo(`${isNew?'إضافة':'تعديل'} المنتج ${p.name}`);goDemo('product-detail');toast('تم حفظ المنتج');break}
 case 'opening-form':{const p=getProduct(),q=Number(v.quantity);if(p.openingDone||p.stock!==0){formError('المخزون الافتتاحي متاح قبل أول حركة فقط.');return}p.stock=q;p.openingDone=true;movements.unshift({productId:p.id,title:'مخزون افتتاحي',qty:q,cost:p.cost,note:'بتكلفة الوحدة المحفوظة',date:'الآن'});logDemo(`مخزون افتتاحي ${p.name}`);goDemo('product-detail');toast('تم حفظ المخزون الافتتاحي');break}
 case 'party-form':{if(!data.has('customer')&&!data.has('supplier')){formError('اختر دورًا واحدًا على الأقل: عميل أو مورد.');return}let p=getParty();if(!p){p={id:Math.max(...parties.map(p=>p.id))+1};parties.push(p)}Object.assign(p,{name:v.name.trim(),phone:v.phone.trim(),address:v.address.trim(),customer:data.has('customer'),supplier:data.has('supplier'),active:data.has('active')});demo.partyId=p.id;demo.partyRole=p.customer?'customer':'supplier';demo.partyFilter=demo.partyRole;logDemo(`حفظ بيانات ${p.name}`);goDemo('party-detail');toast('تم حفظ الطرف');break}
 case 'adjust-form':{const p=getProduct();demo.adjustment={quantity:Number(v.quantity),cost:v.cost===''?null:Math.round(Number(v.cost)*100),reason:v.reason,damaged:data.has('damaged')};sheet.close();showSheet(sheetHead('مراجعة تسوية المخزون')+infoRow('الكمية الحالية',p.stock)+infoRow('الكمية الفعلية',demo.adjustment.quantity)+infoRow('فرق التسوية',demo.adjustment.quantity-p.stock)+`<p class="sheet-help">${esc(v.reason)}</p><div class="button-row"><button class="primary" data-action="adjust-post">اعتماد التسوية</button><button class="secondary" data-action="close-sheet">رجوع</button></div>`);break}
 case 'finance-form':Object.assign(demo.form,v);reviewFinance();break;
 case 'return-form':Object.assign(demo.form,v);reviewReturn();break;
 case 'reference-form':{const list=demo.referenceType==='categories'?categories:units;const name=v.name.trim();if(name&&!list.includes(name))list.push(name);sheet.close();render();toast('تمت إضافة المرجع');break}
 case 'account-form':{if(accounts.some(a=>a.name===v.name.trim())){toast('يوجد حساب بهذا الاسم');return}accounts.push({id:`account-${accounts.length+1}`,name:v.name.trim(),type:v.type,balance:0});sheet.close();logDemo(`إضافة حساب ${v.name}`);render();toast('تمت إضافة الحساب');break}
 case 'store-form':Object.assign(demoShop,{name:v.name.trim(),fullName:v.fullName.trim(),phone:v.phone,address:v.address});logDemo('تعديل بيانات المحل');goDemo('settings');toast('تم حفظ بيانات المحل');break;
 case 'profile-form':demoShop.username=v.username;logDemo('تعديل اسم المستخدم');toast('تم حفظ اسم المستخدم في التجربة');break;
 case 'password-form':if(v.password!==v.confirm){document.querySelector('#password-error').innerHTML='<div class="inline-error">كلمتا المرور غير متطابقتين.</div>';return}sheet.close();toast('تمت معاينة تغيير كلمة المرور');break;
 case 'user-form':{let user=users.find(u=>u.id===demo.userId);if(!user){user={id:Math.max(...users.map(u=>u.id))+1};users.push(user)}Object.assign(user,{name:v.name,username:v.username,role:v.role,discount:Number(v.discount),active:data.has('active'),changePrice:data.has('changePrice')});sheet.close();logDemo(`حفظ المستخدم ${v.name}`);render();toast('تم حفظ المستخدم');break}
 }
});
